@dataclass(frozen=True)
class State:
    count: int = 0
    query: str = ""
def reduce(state: State, action: dict) -> State:
    match action["type"]:
        case "inc":    return replace(state, count=state.count + 1)
        case "search": return replace(state, query=action["query"])
        case _:        return state
class Store:
    def dispatch(self, action):
        self._state = reduce(self._state, action); self._notify()
